<script setup lang="ts">
import { Check } from '@lucide/vue'; import type { ApiProblem } from '~/types/api'
definePageMeta({ middleware: 'auth' }); const { list: listStudents } = useStudents(); const { list: listOfferings } = useCourseOfferings(); const { create } = useEnrollments(); const [{ data: studentsResult }, { data: offeringsResult }] = await Promise.all([useAsyncData('enrollment-students', () => listStudents({ status: 'active', per_page: 100 })), useAsyncData('enrollment-offerings', () => listOfferings({ status: 'open', per_page: 100 }))]); const students = computed(() => studentsResult.value?.data ?? []); const offerings = computed(() => offeringsResult.value?.data ?? []); const studentId = ref<number | ''>(''); const offeringIds = ref<number[]>([]); const submitting = ref(false); const errorMessage = ref('')
function toggle(id: number) { offeringIds.value = offeringIds.value.includes(id) ? offeringIds.value.filter(value => value !== id) : [...offeringIds.value, id] }
async function submit() { submitting.value = true; errorMessage.value = ''; try { await create(Number(studentId.value), offeringIds.value); await navigateTo('/enrollments') } catch (error) { const problem = error as ApiProblem; errorMessage.value = problem.status === 409 ? problem.message : 'Enrollment could not be completed.' } finally { submitting.value = false } }
</script>
<template><div class="page-shell"><PageHeader title="Enroll student" description="The complete selection is committed atomically." /><BaseCard><FormField for="student" label="Student" required><BaseSelect id="student" v-model="studentId" :options="students.map(item => ({ label: `${item.student_number} · ${item.last_name}, ${item.first_name}`, value: item.id }))" /></FormField></BaseCard><BaseCard><h2 class="mb-4 font-semibold">Open course offerings</h2><div class="grid gap-3 md:grid-cols-2"><button v-for="offering in offerings" :key="offering.id" type="button" class="flex gap-3 rounded-xl border p-4 text-left" :class="offeringIds.includes(offering.id) ? 'border-brand-600 bg-brand-50' : 'border-slate-200'" @click="toggle(offering.id)"><span class="grid size-5 place-items-center rounded border"><Check v-if="offeringIds.includes(offering.id)" class="size-3" /></span><span><strong class="block">{{ offering.course?.course_code }} · {{ offering.section }}</strong><small>{{ offering.enrolled_count ?? 0 }} / {{ offering.capacity }} enrolled</small></span></button></div></BaseCard><p v-if="errorMessage" class="text-sm text-red-600">{{ errorMessage }}</p><div class="flex justify-end"><BaseButton :disabled="!studentId || !offeringIds.length" :loading="submitting" @click="submit">Confirm enrollment</BaseButton></div></div></template>
